    long install_mem_raw()
    {
        if (mem_hook_installed_) return 0;
        if (!available()) return kEnotsup;
        int result = hook_wrap(do_mem_abort_, 3,
                               reinterpret_cast<void *>(&shadow_mem_abort_before),
                               nullptr, nullptr);
        if (result != 0) return -result;
        mem_hook_installed_ = true;
        printk("rtgum-stage1: art-shadow mem hook installed\n");
        return 0;
    }

    long install_dbg_raw()
    {
        if (dbg_hook_installed_) return 0;
        if (!available() || !do_debug_exception_) return kEnotsup;
        /* Hook the low-frequency single_step_handler dispatch (called by
         * do_debug_exception for software-step events only) rather than the
         * high-frequency debug exception entry itself. */
        int result = hook_wrap(do_debug_exception_, 3,
                               reinterpret_cast<void *>(&shadow_debug_before),
                               nullptr, nullptr);
        if (result != 0) return -result;
        dbg_hook_installed_ = true;
        printk("rtgum-stage1: art-shadow dbg hook installed\n");
        return 0;
    }

