    if (local_equals(args, "syscall-table-probe")) {
        const unsigned long *table = reinterpret_cast<const unsigned long *>(
            kallsyms_lookup_name("sys_call_table"));
        if (!table)
            return copy_reply(output, output_length, "error=sys-call-table-not-found");
        /* arm64 reserves 244..259. All inspected slots are within the UAPI's
         * known 0..462 range; never index a guessed table tail. */
        const unsigned long candidate = table[244];
        bool uniform = candidate != 0UL;
        for (unsigned int nr = 245U; nr <= 259U; ++nr)
            uniform = uniform && table[nr] == candidate;
        const unsigned long arm64_ni =
            kallsyms_lookup_name("__arm64_sys_ni_syscall");
        const unsigned long generic_ni =
            kallsyms_lookup_name("sys_ni_syscall");
        snprintf(reply,
                 sizeof(reply),
                 "ok reserved=244..259 uniform=%u ni_match=%u ni_symbol=%u memfd279_distinct=%u membarrier283_match=%u",
                 uniform ? 1U : 0U,
                 (candidate == arm64_ni || candidate == generic_ni) ? 1U : 0U,
                 (arm64_ni != 0UL || generic_ni != 0UL) ? 1U : 0U,
                 table[279] != candidate ? 1U : 0U,
                 table[283] != 0UL &&
                         table[283] == kallsyms_lookup_name("__arm64_sys_membarrier")
                     ? 1U
                     : 0U);
        return copy_reply(output, output_length, reply);
    }

