            return copy_reply(output, output_length, "error=invalid-zygote-unlink-arguments");
        const long pid_value = static_cast<long>(pid);
        const long reset_status = g_daemon.unlink_all(pid_value, reply, sizeof(reply));
        const long status = reset_status == 0
                                ? g_linker.unlink_for_pid(pid_value, base)
                                : reset_status;
        /* Sweep inherited daemon mappings after dispatch is disabled. The
         * allocator and linker registries must be retired together: an mm
         * may remain alive after its inherited PTEs have been removed. */
        unsigned int swept = 0;
        unsigned int forgotten = 0;
        if (status == 0) {
            swept = g_allocator.free_all_for_address(base);
            forgotten = g_linker.forget_unmapped_for_base(base);
        }
        if (status == 0)
            snprintf(reply,
                     sizeof(reply),
                     "ok pid=%lu base=0x%lx unlinked=1 daemon_reset=%d swept=%u forgotten=%u",
                     pid,
                     base,
                     reset_status == 0 ? 1 : 0,
                     swept,
                     forgotten);
        else
            snprintf(reply, sizeof(reply), "error=zygote-unlink-failed code=%ld", status);
        return copy_reply(output, output_length, reply);
