        if (!parse_unsigned(cursor, pid) || pid == 0 || pid > 0x7fffffffUL)
            return copy_reply(output, output_length, "error=invalid-zygote-unlink-all-arguments");
        const long pid_value = static_cast<long>(pid);
        /* Disable dispatch first: sweeping images while the daemon still holds
         * a pointer into one would leave the process executing freed code. */
        const long reset_status = g_daemon.unlink_all(pid_value, reply, sizeof(reply));
        /* A busy daemon may still be executing inside one of these images.
         * Preserve every registration and let the caller retry after the
         * quiescent phase; sweeping here used to free live daemon code. */
        if (reset_status != 0) {
            snprintf(reply,
                     sizeof(reply),
                     "error=zygote-unlink-all-daemon-busy code=%ld retry=1",
                     reset_status);
            return copy_reply(output, output_length, reply);
        }
        unsigned int skipped = 0;
        const unsigned int released = g_linker.unlink_all_for_pid(pid_value, skipped);
        snprintf(reply,
                 sizeof(reply),
                 "ok pid=%lu released=%u skipped=%u daemon_reset=%ld",
                 pid,
                 released,
                 skipped,
                 1L);
