        (void)pid;
        const long status = g_daemon.clear_config(reply, sizeof(reply));
        if (status == 0) (void)g_antidebug.revoke_all_manager_grants();
        if (status != 0)
            snprintf(reply, sizeof(reply), "error=daemon-config-clear-failed code=%ld", status);
        return copy_reply(output, output_length, reply);
