    if (local_equals(args, "mem-status")) {
        const unsigned long long acquired =
            __atomic_load_n(&g_memory_io.mm_acquired, __ATOMIC_RELAXED);
        const unsigned long long released =
            __atomic_load_n(&g_memory_io.mm_released, __ATOMIC_RELAXED);
        snprintf(reply, sizeof(reply),
                 "ok reads=%llu writes=%llu bytes-read=%llu bytes-written=%llu denied=%llu mm-acquired=%llu mm-released=%llu mm-balance=%lld inflight=%u",
                 __atomic_load_n(&g_memory_io.reads, __ATOMIC_RELAXED),
                 __atomic_load_n(&g_memory_io.writes, __ATOMIC_RELAXED),
                 __atomic_load_n(&g_memory_io.bytes_read, __ATOMIC_RELAXED),
                 __atomic_load_n(&g_memory_io.bytes_written, __ATOMIC_RELAXED),
                 __atomic_load_n(&g_memory_io.denied, __ATOMIC_RELAXED),
                 acquired,
                 released,
                 static_cast<long long>(acquired - released),
                 __atomic_load_n(&g_memory_io.inflight, __ATOMIC_ACQUIRE));
        return copy_reply(output, output_length, reply);
    }

